      'field.WhatsApp': 'WhatsApp（ワッツアップ）',
      'reader.action.whatsapp': 'WhatsApp（ワッツアップ）を開く',
    },
    'ko': {
      'field.WhatsApp': 'WhatsApp (왓츠앱)',
      'reader.action.whatsapp': 'WhatsApp (왓츠앱) 열기',
    },
  };

  static const _widgetThemeOverrides = <String, Map<String, String>>{
    'es': {'settings.widgetTheme': 'Tema del widget', 'settings.widgetTheme.light': 'Claro', 'settings.widgetTheme.black': 'Negro'},
    'en': {'settings.widgetTheme': 'Widget theme', 'settings.widgetTheme.light': 'Light', 'settings.widgetTheme.black': 'Black'},
    'pt': {'settings.widgetTheme': 'Tema do widget', 'settings.widgetTheme.light': 'Claro', 'settings.widgetTheme.black': 'Preto'},
    'fr': {'settings.widgetTheme': 'Thème du widget', 'settings.widgetTheme.light': 'Clair', 'settings.widgetTheme.black': 'Noir'},
    'zh': {'settings.widgetTheme': '小组件主题', 'settings.widgetTheme.light': '浅色', 'settings.widgetTheme.black': '黑色'},
    'de': {'settings.widgetTheme': 'Widget-Thema', 'settings.widgetTheme.light': 'Hell', 'settings.widgetTheme.black': 'Schwarz'},
    'ja': {'settings.widgetTheme': 'ウィジェットのテーマ', 'settings.widgetTheme.light': 'ライト', 'settings.widgetTheme.black': '黒'},
    'ko': {'settings.widgetTheme': '위젯 테마', 'settings.widgetTheme.light': '밝게', 'settings.widgetTheme.black': '검정'},
    'it': {'settings.widgetTheme': 'Tema del widget', 'settings.widgetTheme.light': 'Chiaro', 'settings.widgetTheme.black': 'Nero'},
    'ru': {'settings.widgetTheme': 'Тема виджета', 'settings.widgetTheme.light': 'Светлая', 'settings.widgetTheme.black': 'Чёрная'},
  };

  String t(String key, [String? fallback]) {
    // QR type names live in the primary catalog so selectors, filters and
    // imported-code labels always use the same locale-specific value.
    if (key.startsWith('type.')) {
      final typeValue = _values[key]?[languageCode];
      if (typeValue != null) return typeValue;
    }
    final whatsappDisplay = _whatsappDisplayOverrides[languageCode]?[key];
    if (whatsappDisplay != null) return whatsappDisplay;
    final widgetThemeDisplay = _widgetThemeOverrides[languageCode]?[key];
    if (widgetThemeDisplay != null) return widgetThemeDisplay;
    final override = _languageOverrides[languageCode]?[key];
    if (override != null) return override;
    final secondary = _secondaryOverrides[languageCode]?[key];
    if (secondary != null) return secondary;
    final direct = _values[key];
    if (direct != null) {
      final localized = direct[languageCode];
      if (localized != null) return localized;
      if (key.startsWith('help.')) return _helpFallback(key, fallback);
      return direct['en'] ?? fallback ?? key;
    }
    final normalized = _normalizeKey(key);
    for (final entry in _values.entries) {
      if (_normalizeKey(entry.key) == normalized) {
        return entry.value[languageCode] ?? entry.value['en'] ?? fallback ?? key;
      }
    }
    if (key.startsWith('help.')) return _helpFallback(key, fallback);
    return fallback ?? key;
  }

  String _helpFallback(String key, String? fallback) {
    final field = key.substring(5);
    final guidance = const {
      'pt': 'Preencha este campo com a informação correspondente.',
      'fr': 'Renseignez ce champ avec l’information correspondante.',
      'de': 'Füllen Sie dieses Feld mit den entsprechenden Angaben aus.',
      'it': 'Compila questo campo con le informazioni corrispondenti.',
      'ru': 'Заполните это поле соответствующей информацией.',
      'zh': '请填写与此字段对应的信息。',
      'ja': 'この項目に対応する情報を入力してください。',
      'ko': '이 항목에 해당하는 정보를 입력하세요.',
    }[languageCode];
    if (guidance != null) return '$guidance ${fieldLabel(field)}.';
    return fallback ?? field;
  }

  static String _normalizeKey(String value) => value
      .replaceAll('Ã¡', 'á').replaceAll('Ã©', 'é').replaceAll('Ã­', 'í')
      .replaceAll('Ã³', 'ó').replaceAll('Ãº', 'ú').replaceAll('Ã±', 'ñ')
      .replaceAll('Ã', 'Á').replaceAll('Ã‰', 'É').replaceAll('Ã', 'Í')
      .replaceAll('Ã“', 'Ó').replaceAll('Ãš', 'Ú').replaceAll('Ã‘', 'Ñ');

  String fieldLabel(String key) => t('field.$key', key);

  String languageName(String code) => const {
    'es': 'Español',
    'en': 'English',
    'pt': 'Português',
    'fr': 'Français',
    'zh': '中文',
    'de': 'Deutsch',
    'ja': '日本語',
    'ko': '한국어',
    'it': 'Italiano',
    'ru': 'Русский',
  }[code] ?? code;

  String languageFlag(String code) => const {
    'es': '🇪🇸', 'en': '🇬🇧', 'pt': '🇵🇹', 'fr': '🇫🇷', 'zh': '🇨🇳',
    'de': '🇩🇪', 'ja': '🇯🇵', 'ko': '🇰🇷', 'it': '🇮🇹', 'ru': '🇷🇺',
  }[code] ?? '🌐';

  String typeLabel(Object type) {
    final raw = type is Enum ? type.name : type.toString().split('.').last;
    final compact = raw.trim().toLowerCase().replaceAll(RegExp(r'[\s_-]+'), '');
    // Accept both enum names and persisted/display aliases. This is useful
    // for imported backups created by older versions of the app.
    final normalized = <String, String>{
      'wifi': 'wifi',
      'whatsapp': 'whatsapp',
      'sms': 'sms',
      'url': 'url',
      'link': 'url',
      'enlace': 'url',
      'contact': 'contact',
      'contacto': 'contact',
    }[compact] ?? raw.split('.').last;
    return t('type.$normalized', raw);
  }

  static QrFriLocalizations of(BuildContext context) => Localizations.of<QrFriLocalizations>(context, QrFriLocalizations) ?? const QrFriLocalizations(Locale('en'));
}

class _QrFriDelegate extends LocalizationsDelegate<QrFriLocalizations> {
  const _QrFriDelegate();
  @override bool isSupported(Locale locale) => QrFriLocalizations.languageCodes.contains(locale.languageCode);
  @override Future<QrFriLocalizations> load(Locale locale) async => QrFriLocalizations(locale);
  @override bool shouldReload(_QrFriDelegate old) => false;
}

extension QrFriContextLocalization on BuildContext {
  QrFriLocalizations get qrL10n => QrFriLocalizations.of(this);
}
